45	// repoDetailColumns / repoDetailRow extend the shared repo view with the
46	// entire:// clone URL for the single-repo `get` output. The list view stays on
47	// the lean repoColumns — a full clone URL per row would bloat the table — but a
48	// person inspecting one repo wants the URL they can paste into `git clone`
49	// (COR-699). REMOTE is "-" until the repo is provisioned enough to have a
50	// resolvable cluster host + path.
51	var repoDetailColumns = []string{"ID", "NAME", "PROJECT", "CLUSTER", "STATE", "REMOTE"}
52	
53	func repoDetailRow(r coreapi.Repo) []string {
54		remote := repoRemoteURL(r)
55		if remote == "" {
56			remote = "-"
57		}
58		return append(repoRow(r), remote)
59	}
