61	// repoRemoteURL synthesizes the entire:// clone/remote URL for a repo from
62	// its resolved cluster host and path — the form `git clone` and
63	// `git remote add` accept, which git-remote-entire reads back as the repo
64	// slug from the URL path. Returns "" when either coordinate is missing (a
65	// still-provisioning repo may not have them yet); a half-formed URL is worse
66	// than none.
67	func repoRemoteURL(r coreapi.Repo) string {
68		host := strings.TrimSpace(r.ClusterHost.Or(""))
69		path := strings.TrimSpace(r.Path.Or(""))
70		if host == "" || path == "" {
71			return ""
72		}
73		return "entire://" + host + "/" + strings.TrimPrefix(path, "/")
74	}
