76	// repoCreateOutput renders a created repo as JSON with a synthesized `remote`
77	// field merged in — the entire:// URL callers paste into `git clone` or
78	// `git remote add`. The repo carries a custom marshaler plus arbitrary
79	// additional properties, so it can't simply be embedded in a wrapper struct;
80	// instead it's round-tripped through its own encoder and the remote is merged
81	// into the resulting object. The synthesis only fills a gap: if the wire
82	// object already carries a `remote` (a future first-class field, or one
83	// arriving via additional properties) it's left untouched, so the
84	// server-provided value always wins. The field is omitted when the clone
85	// coordinates aren't resolvable yet rather than emitted half-formed.
86	func repoCreateOutput(r *coreapi.Repo) (any, error) {
87		if r == nil {
88			return nil, errors.New("nil repo")
89		}
90		raw, err := json.Marshal(r)
91		if err != nil {
92			return nil, fmt.Errorf("encode repo: %w", err)
93		}
94		var obj map[string]json.RawMessage
95		if err := json.Unmarshal(raw, &obj); err != nil {
96			return nil, fmt.Errorf("decode repo: %w", err)
97		}
98		if _, ok := obj["remote"]; !ok {
99			if remote := repoRemoteURL(*r); remote != "" {
100				encoded, err := json.Marshal(remote)
101				if err != nil {
102					return nil, fmt.Errorf("encode remote: %w", err)
103				}
104				obj["remote"] = encoded
105			}
106		}
107		return obj, nil
108	}
