110	// parseObjectFormat maps the CLI flag value to the wire enum, rejecting
111	// anything other than the two accepted values so a typo fails fast
112	// client-side rather than as an opaque 422 from the server.
113	func parseObjectFormat(s string) (coreapi.CreateRepoInputBodyObjectFormat, error) {
114		switch s {
115		case "sha1":
116			return coreapi.CreateRepoInputBodyObjectFormatSHA1, nil
117		case "sha256":
118			return coreapi.CreateRepoInputBodyObjectFormatSHA256, nil
119		default:
120			return "", fmt.Errorf("invalid object format %q: must be \"sha1\" or \"sha256\"", s)
121		}
122	}
