145	// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
146	// into its provider ("github") and handle ("alice"). Accounts are addressed by
147	// this friendly form; a value with no "provider:" prefix is rejected so the
148	// user gets a clear hint rather than a confusing lookup miss.
149	func parseQualifiedHandle(ref string) (provider, handle string, err error) {
150		provider, handle, ok := strings.Cut(ref, ":")
151		if !ok || provider == "" || handle == "" {
152			return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
153		}
154		return provider, handle, nil
155	}
