157	// resolveProjectRef turns a project reference (ULID or name) into its ULID. A
158	// ULID is returned unchanged; a name is resolved via the server's
159	// case-insensitive by-name lookup (the same call `entire project list --name`
160	// uses). Project names are globally unique, so a name maps to at most one project.
161	func resolveProjectRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
162		if looksLikeULID(ref) {
163			return ref, nil
164		}
165		out, err := c.ListProjects(ctx, coreapi.ListProjectsParams{Name: coreapi.NewOptString(ref)})
166		if err != nil {
167			if isCoreNotFound(err) {
168				return "", noProjectNamedErr(ref)
169			}
170			return "", err
171		}
172		project, ok := out.Project.Get()
173		if !ok {
174			return "", noProjectNamedErr(ref)
175		}
176		return project.ID, nil
177	}
