179	// resolveRepoRef turns a repo reference into its ULID. A ULID passes through.
180	// A name requires a project scope (projectRef, itself a name or ULID) because
181	// repo names are unique only within a project: the repo is resolved via the
182	// server's case-insensitive by-name lookup, scoped to that project. Like the
183	// org/project endpoints, a name-filtered list returns the single match under the
184	// response's singular `repo` field (the plural `repos` is only populated for an
185	// unfiltered page) — reading `repos` here was the COR-699 bug.
186	func resolveRepoRef(ctx context.Context, c *coreapi.Client, ref, projectRef string) (string, error) {
187		if looksLikeULID(ref) {
188			return ref, nil
189		}
190		if projectRef == "" {
191			return "", fmt.Errorf("repo %q is a name; pass --project <name|ULID> to resolve it, or use a repo ULID", ref)
192		}
193		projID, err := resolveProjectRef(ctx, c, projectRef)
194		if err != nil {
195			return "", err
196		}
197		out, err := c.ListProjectRepos(ctx, coreapi.ListProjectReposParams{ProjectId: projID, Name: coreapi.NewOptString(ref)})
198		if err != nil {
199			if isCoreNotFound(err) {
200				return "", noRepoNamedErr(ref)
201			}
202			return "", err
203		}
204		repo, ok := out.Repo.Get()
205		if !ok {
206			return "", noRepoNamedErr(ref)
207		}
208		return repo.ID, nil
209	}
