	grep.Dir = strings.TrimSpace(string(root))
	out, err := grep.Output()
	if err != nil {
		t.Fatalf(`git grep for "status" found nothing, which cannot be right: %v`, err)
	}

	var checked int
	for line := range strings.SplitSeq(strings.TrimSpace(string(out)), "\n") {
		path, rest, ok := strings.Cut(line, ":")
