#!/usr/bin/env python3
"""Audit exec.Command git call sites in test files for GitIsolatedEnv usage."""
import os
import re
import sys

ROOT = sys.argv[1]
CALL = re.compile(r'exec\.Command(Context)?\([^)]*"git"')
ISO = re.compile(r'GitIsolatedEnv|isolatedSSHEnv|IsolateGitConfigEnv')
ENVSET = re.compile(r'\.Env\s*=')

hits = []
for dirpath, _, files in os.walk(ROOT):
    if "/.git" in dirpath or "/vendor" in dirpath:
        continue
    for fn in files:
        if not fn.endswith(".go"):
            continue
        # test files plus test-only support files in test dirs
        p = os.path.join(dirpath, fn)
        rel = os.path.relpath(p, ROOT)
        is_testish = fn.endswith("_test.go") or "/testutil/" in p or "/integration_test/" in p or "/e2e/" in rel
        if not is_testish:
            continue
        lines = open(p, encoding="utf-8").read().splitlines()
        for i, line in enumerate(lines):
            if not CALL.search(line):
                continue
            window = "\n".join(lines[i : i + 8])
            if ISO.search(window):
                status = "ISOLATED"
            elif ENVSET.search(window):
                status = "ENV-OTHER"
            else:
                status = "BARE"
            hits.append((status, rel, i + 1, line.strip()[:110]))

order = {"BARE": 0, "ENV-OTHER": 1, "ISOLATED": 2}
hits.sort(key=lambda h: (order[h[0]], h[1], h[2]))
counts = {}
for h in hits:
    counts[h[0]] = counts.get(h[0], 0) + 1
print("counts:", counts)
for status, rel, ln, src in hits:
    if status != "ISOLATED":
        print(f"{status:9} {rel}:{ln}  {src}")

