"""List remaining raw exec git sites in test code with their shape."""
import os
import re
import sys

ROOT = sys.argv[1]
CALL = re.compile(r'exec\.Command(Context)?\([^)]*"git"')

per_file = {}
for dirpath, dirs, files in os.walk(ROOT):
    if ".git" in dirs:
        dirs.remove(".git")
    for fn in files:
        if not fn.endswith(".go"):
            continue
        p = os.path.join(dirpath, fn)
        rel = os.path.relpath(p, ROOT)
        if not (fn.endswith("_test.go") or "/testutil/" in p or "/integration_test/" in p or rel.startswith("e2e/")):
            continue
        if rel.endswith("gitenv/gitenv.go"):
            continue
        lines = open(p, encoding="utf-8").read().splitlines()
        for i, line in enumerate(lines):
            if CALL.search(line) and "exec.Command" in line and '`' not in line:
                window = "\n".join(lines[i : i + 10])
                shape = []
                if "CombinedOutput" in window:
                    shape.append("combined")
                if re.search(r"\.Output\(\)", window):
                    shape.append("output")
                if "Fatalf" in window or "NoError" in window:
                    shape.append("fatal")
                if "Skipf" in window:
                    shape.append("skip")
                if "Stdin" in window or "Stdout" in window:
                    shape.append("stdio")
                per_file.setdefault(rel, []).append((i + 1, ",".join(shape) or "?", line.strip()[:90]))

for rel in sorted(per_file):
